CURRENT_LANG = None


def get_lang():
    """Retorna o idioma atual (pt-BR ou en)."""
    preview_lang = os.environ.get("OMNI_PREVIEW_LANG")
    if preview_lang in ("pt-BR", "en"):
        return preview_lang
    global CURRENT_LANG
    if CURRENT_LANG in ("pt-BR", "en"):
        return CURRENT_LANG
    try:
        with open(LANG_FILE) as f:
            lang = f.read().strip()
            CURRENT_LANG = lang if lang in ("pt-BR", "en") else DEFAULT_LANG
            return CURRENT_LANG
    except OSError:
        CURRENT_LANG = DEFAULT_LANG
        return CURRENT_LANG


def set_lang(lang):
    """Salva o idioma escolhido."""
    if lang not in ("pt-BR", "en"):
        return
    global CURRENT_LANG
    CURRENT_LANG = lang
    try:
        os.makedirs(os.path.dirname(LANG_FILE), exist_ok=True)
        with open(LANG_FILE, "w") as f:
            f.write(lang)
    except OSError:
        pass


def _(key):
    """Traduz uma chave para o idioma atual."""
    lang = get_lang()
    entry = TRANSLATIONS.get(key, {})
    return entry.get(lang, entry.get("pt-BR", key))


# Começo das mensagens que indicam falha (a tela usa para escolher aviso ou sucesso).
FAIL_PREFIXES = ("Erro", "Não", "Falta", "Desligue", "Tire", "Carregue", "Poucas", "Pare", "Ligue", "O PC",
                 "Could not", "Cannot", "Not ", "No ", "Was not", "Wi-Fi adapter not", "Expected frequency",
                 "dtc ", "dnsmasq is", "Unplug", "Charge to", "Too few", "Stop calibration", "Enable USB",
                 "PC did not", "The audio library", "A library", "Original game", "hud/omni_hud.so is")


def is_failure(text):
    """True se a mensagem de resultado for um erro, em qualquer idioma."""
    return str(text).startswith(FAIL_PREFIXES)


def available_languages():
    """Retorna lista de idiomas disponíveis."""
    return [
        ("pt-BR", _("lang_ptbr")),
        ("en", _("lang_en")),
    ]